      {
        "t": 23.32,
        "who": "Dad",
        "text": "Antarctica gets twenty four hours of sunshine in summer. Double Singapore. So it's basically double Sentosa."
      },
      {
        "t": 33.23,
        "who": "Tara",
        "text": "My father is going to Antarctica with one sock. I've started writing his speech for the penguins."
      }
