    "strand": "Y8 Geography Short",
    "episodeTitle": "Concrete Jungle Fever",
    "index": 1,
    "totalInTopic": 5,
    "title": "Concrete Jungle Fever — Story Hook",
    "summary": "Deal alert! Megacity weekend! Three cities, two days, forty hours of layovers!",
    "startSec": 0.0,
    "endSec": 37.45,
    "durationSec": 37.45,
    "src": "/videos/cities-megacities.mp4",
    "poster": "/videos/posters/cities-megacities.jpg",
    "captions": [
      {
        "t": 1.06,
        "who": "Mum",
        "text": "Deal alert! Megacity weekend! Three cities, two days, forty hours of layovers!"
      },
      {
        "t": 6.46,
        "who": "Tara",
        "text": "Mum. That's not a holiday. That's a hostage situation with peanuts."
      },
      {
        "t": 11.96,
        "who": "Dad",
        "text": "Why fly to a megacity? We live in one. Singapore is the greatest city on Earth. Greatest means mega."
      },
      {
        "t": 18.72,
        "who": "Tara",
        "text": "Dad, a megacity needs ten million people. Singapore has about six million."
      },
      {
        "t": 23.87,
        "who": "Dad",
        "text": "So we're four million short. Easy. I've told my family group chat to move in."
      },
      {
        "t": 31.88,
        "who": "Tara",
        "text": "My father is trying to grow a country by group chat. He still can't leave the group chat."
      }
    ]
